from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.option.SetFilter(
            lambda universe: universe
                .CallsOnly()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.expiration_liquidated_today = False

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, self.consolidator)

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.expiration_liquidated_today and today != getattr(
            self, "_expiration_liquidation_date", None
        ):
            self.expiration_liquidated_today = False

        self._handle_unexpected_spy_position()

        if self.held_symbol is not None and self.entry_price is not None:
            self._evaluate_exit(slice)

        if not self.expiration_liquidated_today:
            bar = slice.Bars.get(self.spy.Symbol)
            if bar is not None and self._is_regular_session_minute(bar.EndTime):
                self.consolidator.Update(bar)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if not self._is_regular_session_bar(bar):
            return

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        end_time = bar.EndTime
        if not bullish_cross:
            return

        if not (end_time.hour == 9 and end_time.minute >= 45 or
                10 <= end_time.hour <= 13 or
                end_time.hour == 14 and end_time.minute <= 30):
            return

        if self.expiration_liquidated_today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        self._try_enter()

    def _try_enter(self):
        slice_data = getattr(self, "_current_slice", None)
        if slice_data is None:
            self.Debug("Skipped entry: current Slice unavailable")
            return

        chain = slice_data.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        algorithm_date = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no eligible expiration")
            return

        expiration = eligible_expirations[0]
        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_exit(self, slice_data):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        quote = slice_data.QuoteBars.get(self.held_symbol)

        target_hit = False
        if quote is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                target_hit = midpoint >= 1.50 * self.entry_price

        time_stop = self._is_expiration_eve_time()
        if not target_hit and not time_stop:
            return

        reason = "profit target" if target_hit else "expiration-eve time stop"
        self._submit_exit(reason)

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsFilled():
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        symbol = order_event.Symbol

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_symbol = symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = symbol.ID.Date.date()
                self.Debug(
                    "Entry filled: {} @ {:.2f}".format(symbol, self.entry_price)
                )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if self.Portfolio[symbol].Quantity == 0:
                self.Debug("Exit filled: {}".format(symbol))
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None
                self.entry_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment: liquidating SPY")
        self._liquidate_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self.Debug("Unexpected SPY position detected; liquidating")
            self._liquidate_spy_position()

    def _liquidate_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy.Symbol, -quantity)

    def _is_expiration_eve_time(self):
        if self.expiration_date is None:
            return False

        if self.Time.hour != 15 or self.Time.minute < 45:
            return False

        current_date = self.Time.date()
        if current_date >= self.expiration_date:
            return False

        next_open_date = current_date + timedelta(days=1)
        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(next_open_date):
            next_open_date += timedelta(days=1)

        return next_open_date == self.expiration_date

    def _is_regular_session_minute(self, end_time):
        return (
            end_time.hour > 9 or
            end_time.hour == 9 and end_time.minute >= 31
        ) and (
            end_time.hour < 16
        )

    def _is_regular_session_bar(self, bar):
        return (
            bar.EndTime.hour > 9 or
            bar.EndTime.hour == 9 and bar.EndTime.minute >= 35
        ) and (
            bar.EndTime.hour < 16
        )

    def OnEndOfDay(self, symbol):
        if self.held_symbol is not None and self.expiration_date is not None:
            if self.Time.date() >= self.expiration_date:
                self._submit_exit("expiration liquidation")
                self.expiration_liquidated_today = True
                self._expiration_liquidation_date = self.Time.date()

    def OnSecuritiesChanged(self, changes):
        pass
