from AlgorithmImports import *
from collections import OrderedDict
from datetime import datetime, timedelta, time


class SpyBullishCrossoverCalls(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .CallsOnly()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.spy_option = option.Symbol

        self.fast_window = []
        self.slow_window = []
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bars = {}
        self.current_bucket = None

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_today and current_date != self.no_entry_today:
            self.no_entry_today = False

        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            self._process_expiration_and_time_stop(slice)

            if self.held_symbol is not None and self.entry_price is not None:
                self._process_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        local_time = spy_bar.EndTime.astimezone(self.TimeZone)
        if local_time.date() != current_date:
            return

        if local_time.time() < time(9, 30) or local_time.time() > time(16, 0):
            return

        self._update_five_minute_bar(spy_bar)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_start = minute_bar.Time.astimezone(self.TimeZone)

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        minutes_from_open = (
            local_start.hour * 60 + local_start.minute
            - (9 * 60 + 30)
        )
        bucket_number = minutes_from_open // 5
        bucket_start = datetime.combine(
            local_start.date(),
            time(9, 30)
        ) + timedelta(minutes=bucket_number * 5)

        bucket_key = bucket_start
        bucket = self.minute_bars.setdefault(bucket_key, [])

        if not any(bar.Time == minute_bar.Time for bar in bucket):
            bucket.append(minute_bar)

        if len(bucket) < 5:
            return

        if len(bucket) > 5:
            del self.minute_bars[bucket_key]
            return

        bucket.sort(key=lambda bar: bar.Time)
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if [bar.Time.astimezone(self.TimeZone) for bar in bucket] != expected_times:
            del self.minute_bars[bucket_key]
            return

        consolidated = TradeBar(
            bucket_start,
            self.spy,
            bucket[0].Open,
            max(bar.High for bar in bucket),
            min(bar.Low for bar in bucket),
            bucket[-1].Close,
            sum(bar.Volume for bar in bucket),
            timedelta(minutes=5)
        )

        del self.minute_bars[bucket_key]
        self._process_five_minute_bar(consolidated)

    def _process_five_minute_bar(self, bar: TradeBar):
        close = float(bar.Close)

        self.slow_window.append(close)
        if len(self.slow_window) > 20:
            self.slow_window.pop(0)

        self.fast_window.append(close)
        if len(self.fast_window) > 5:
            self.fast_window.pop(0)

        current_fast = None
        current_slow = None

        if len(self.fast_window) == 5:
            current_fast = sum(self.fast_window) / 5.0

        if len(self.slow_window) == 20:
            current_slow = sum(self.slow_window) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        bar_end = bar.EndTime.astimezone(self.TimeZone)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if (
            bullish_cross
            and eligible_time
            and self.held_symbol is None
            and self.entry_ticket is None
            and not self.no_entry_today
        ):
            self._try_enter_call(bar.Close)

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def _try_enter_call(self, spy_price: float):
        chain = self.CurrentSlice.OptionChains.get(self.spy_option)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        minimum_expiration = today + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Symbol.ID.OptionRight == OptionRight.Call
            and contract.Symbol.ID.Date.date() >= minimum_expiration
        ]

        if not contracts:
            self.Debug("Skipped entry: no expiration satisfies the 7-day rule.")
            return

        expiration = min(
            contract.Symbol.ID.Date.date()
            for contract in contracts
        )

        strike_floor = float(spy_price) * 1.01
        candidates = [
            contract for contract in contracts
            if contract.Symbol.ID.Date.date() == expiration
            and float(contract.Symbol.ID.Strike) >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Symbol.ID.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiration={expiration}, strike={selected.Symbol.ID.Strike}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.expiration_date = (
                        order_event.Symbol.ID.Date.date()
                    )
                    self.entry_ticket = None
                    self.Debug(
                        f"Entry filled: {self.held_symbol} "
                        f"at {self.entry_price:.4f}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Exit filled: {order_event.Symbol}")
                    self._clear_position_state()
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        if order_event.Status == OrderStatus.Filled:
            try:
                if order_event.OrderType == OrderType.OptionExercise:
                    self.Debug(
                        f"Unexpected option exercise/assignment: "
                        f"{order_event.Symbol}"
                    )
                    equity_quantity = self.Portfolio[self.spy].Quantity
                    if equity_quantity != 0:
                        self.MarketOrder(self.spy, -equity_quantity)
            except Exception:
                pass

    def _process_profit_target(self, slice: Slice):
        chain = slice.OptionChains.get(self.spy_option)
        if chain is None:
            return

        contract = next(
            (
                item for item in chain
                if item.Symbol == self.held_symbol
            ),
            None
        )

