                    self.time_stop_date = self.GetPreviousTradingDate(
                        self.expiration_date
                    )
                    self.entry_ticket = None
                    self.Debug("Entry filled: {0} at {1}".format(
                        self.held_option, self.entry_price
                    ))
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Submitted
                ):
                    if order_event.Status in (
                        OrderStatus.Canceled,
                        OrderStatus.Invalid
                    ):
                        self.entry_ticket = None
                return

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {0}".format(order_event.Symbol))
                    self.exit_ticket = None
                    self.held_option = None
                    self.entry_price = None
                    self.expiration_date = None
                    self.time_stop_date = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def GetPreviousTradingDate(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def HandleUnexpectedSpyPosition(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested or holding.Quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(self.spy, -holding.Quantity)

    def OnEndOfAlgorithm(self):
        if self.held_option is not None:
            self.Debug("Unexpected option position remains at algorithm end.")
